```text
class PrimeDatabase {
  var database: map<int, bool>

  ghost predicate prime(n: int)
    requires n >= 2
  {
    forall d :: 2 <= d < n ==> n % d != 0
  }

  constructor()
    ensures database == map[]
  {
    database := map[];
  }

  method InsertPrime(n: nat)
    modifies database
    requires forall i | i in database.Keys :: (database[i] == true <==> (i >= 2 && prime(i)))
    ensures forall i | i in database.Keys :: (database[i] == true <==> (i >= 2 && prime(i)))
  {
    var isPrime := true;
    if n < 2 {
      isPrime := false;
    } else {
      var d := 2;
      while d < n
        invariant 2 <= d <= n
        invariant isPrime == true <==> forall k :: 2 <= k < d ==> n % k != 0
      {
        if n % d == 0 {
          isPrime := false;
        }
        d := d + 1;
      }
      assert isPrime == true <==> prime(n);
    }
    if isPrime {
      assert n >= 2;
      assert prime(n);
      database := database[n := true];
    }
  }
}
```

